"use strict";
(()=>{const L=window.Lab;if(!L||!L.$('complex-lab'))return;
L.init(['real','imag','operation'],()=>{const x=L.range('real'),y=L.range('imag'),op=L.$('operation').value,[u,v]=op==='j'?[-y,x]:op==='2'?[2*x,2*y]:[-x,-y],g=L.$('drawing');g.replaceChildren();const X=x=>330+48*x,Y=y=>230-48*y;for(let n=-4;n<=4;n++){g.append(L.svg('line',{x1:X(n),y1:Y(4),x2:X(n),y2:Y(-4),class:'gridline'}),L.svg('line',{x1:X(-4),y1:Y(n),x2:X(4),y2:Y(n),class:'gridline'}));if(n!==0)g.append(L.svg('text',{x:X(n),y:248,'text-anchor':'middle',class:'svg-small'},n),L.svg('text',{x:316,y:Y(n)+5,'text-anchor':'end',class:'svg-small'},n));}g.append(L.svg('path',{d:'M115 230H550M330 445V20',class:'axis'}),L.svg('text',{x:540,y:219,class:'svg-small'},'實部'),L.svg('text',{x:341,y:29,class:'svg-small'},'虛部'));[[x,y,'#172a45','原箭頭'],[u,v,'#345cdf','結果']].forEach(([a,b,c,label])=>{g.append(L.svg('line',{x1:330,y1:230,x2:X(a),y2:Y(b),stroke:c,'stroke-width':4}),L.svg('circle',{cx:X(a),cy:Y(b),r:6,fill:c}),L.svg('text',{x:X(a)+10,y:Y(b)-12,class:'svg-label'},label));});const mag=Math.hypot(u,v);L.text('result-primary',L.fmt(u)+(v<0?' − ':' + ')+L.fmt(Math.abs(v))+'j');L.text('result-secondary','長度 '+L.fmt(mag));L.text('feedback',mag===0?'零複數仍在原點，長度為 0；沒有一個可定義的方向角。':(op==='j'?'乘 j：把 (x,y) 改成 (−y,x)，逆時針轉 90°，長度不變。':op==='2'?'乘 2：兩個座標一起加倍，方向不變，長度加倍。':'乘 −1：兩個座標反號，相當於旋轉 180°。')+' 結果方向角 '+L.fmt(Math.atan2(v,u)*180/Math.PI,1)+'°；實軸與虛軸每格長度相同。');});})();
